package com.footballacademy.controllers_rest;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import com.footballacademy.services.scouting.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/scouting") public class ScoutingController { private final ScoutingService scoutingService; private final MatchEventService matchEventService; private final TalentScoringService talentScoringService; private final ScouterAssignmentService assignmentService; private final ScoutingReportRepository reports; private final ScoutingCriterionService criterionService; private final VideoAnalysisService videoAnalysisService; public ScoutingController(ScoutingService scoutingService, MatchEventService matchEventService, TalentScoringService talentScoringService, ScouterAssignmentService assignmentService, ScoutingReportRepository reports, ScoutingCriterionService criterionService, VideoAnalysisService videoAnalysisService){this.scoutingService=scoutingService;this.matchEventService=matchEventService;this.talentScoringService=talentScoringService;this.assignmentService=assignmentService;this.reports=reports;this.criterionService=criterionService;this.videoAnalysisService=videoAnalysisService;} @PostMapping("/reports") public ScoutingReport createReport(@RequestParam Long playerId,@RequestParam Long scouterId,@RequestParam(required=false) Long matchId){return scoutingService.createReport(playerId, scouterId, matchId);} @PutMapping("/reports/{id}") public ScoutingReport updateReport(@PathVariable Long id,@RequestBody ScoutingReport report){return scoutingService.updateReport(id, report);} @PostMapping("/reports/{id}/approve") public void approve(@PathVariable Long id){scoutingService.approveReport(id);} @PostMapping("/reports/{id}/reject") public void reject(@PathVariable Long id){scoutingService.rejectReport(id);} @GetMapping("/reports/player/{playerId}") public List<ScoutingReport> reportsByPlayer(@PathVariable Long playerId){return reports.findByPlayer_Id(playerId);} @GetMapping("/shortlist") public List<Player> shortlist(@RequestParam Long academyId,@RequestParam(required=false) Long divisionId){return scoutingService.getShortlist(academyId, divisionId);} @PostMapping("/events") public MatchEvent addEvent(@RequestParam Long matchId,@RequestParam Long playerId,@RequestBody MatchEvent event){return matchEventService.addEvent(matchId, playerId, event);} @GetMapping("/matches/{matchId}/timeline") public List<MatchEvent> timeline(@PathVariable Long matchId){return matchEventService.getMatchTimeline(matchId);} @PostMapping("/talent-score/{playerId}") public TalentScore score(@PathVariable Long playerId){return talentScoringService.generateTalentScore(playerId);} @PostMapping("/assignments") public ScoutingAssignment assign(@RequestParam Long academyId,@RequestParam Long divisionId,@RequestParam Long scouterId){return assignmentService.assignScouter(academyId, divisionId, scouterId);} @GetMapping("/assignments/{scouterId}") public List<ScoutingAssignment> assignments(@PathVariable Long scouterId){return assignmentService.getAssignments(scouterId);} @GetMapping("/criteria") public List<ScoutingCriterion> criteria(){return criterionService.listActiveCriteria();} @PostMapping("/criteria") public ScoutingCriterion createCriterion(@RequestBody ScoutingCriterion criterion){return criterionService.createCriterion(criterion);} @PostMapping("/video/{assetId}/analysis") public VideoAnalysis startVideoAnalysis(@PathVariable Long assetId){return videoAnalysisService.startAnalysis(assetId);} }
